        switch (input.fallbackNullableKind()) {
          case JSPECIFY:
            return " @org.jspecify.annotations.Nullable ";
          case SPECIFIED_TYPEUSE:
            return " @" + input.style().fallbackNullableAnnotationName() + " ";
          default:
